		logger = slog.Default()
	}
	return &MilestoneService{
		BaseService: NewBaseServiceWithOptions("milestone", nil, WithLogger(logger)),
		logger:      logger,
		subscriber:  subscriber,
		client:      client,
		cfg:         cfg,
	}
}

